for d in D:
 day=d['day'];prefix=f'C{day:02}'
 out=f'<nav><a href="index.html">← Thirty-day review</a> · <a href="/">Aleph workspace and uploads</a></nav><section class="hero"><p class="eyebrow">Phase 1 · Day {day} of 10</p><h1>{d["title"]}</h1><p class="sub">{d["goal"]}</p><div class="meta"><span>Calculus refresher</span><span>6 practice problems + opening and exit checks</span><span>Study day; no calendar deadline</span></div><p>Prerequisites: {d["prereq"]}</p></section>'
 out+='<section class="panel"><h2>How to work today</h2><p>Aim for roughly 75–90 minutes: opening 5, reading and worked examples 30, practice 30–40, exit and correction 10–15. This is a provisional allocation. If time runs out, mark what you did not reach. Problems 1–4 are the core; 5–6 extend or combine ideas. Attempt before opening solutions. Record any hints or prior exposure.</p><p>Write on paper and upload through <strong>Aleph → Subjects → Calculus: 30-day review</strong> for the existing submission and feedback workflow. The boxes on this page are a browser-local scratchpad; export a copy before changing devices.</p></section>'
 out+=f'<article class="problem" data-problem="{prefix}-OPEN"><h2>Opening check · before reading</h2><p>{d["opening"]}</p><textarea aria-label="Opening response" data-answer="{prefix}-OPEN" rows="3" placeholder="Record your initial reasoning; keep it when making corrections."></textarea></article>'
 out+='<section class="panel accent">'+d['story']+'</section><h2 class="section-label">Two worked examples · follow the decisions</h2>'
 for i,(title,q,a) in enumerate(d['worked'],1):out+=f'<section class="panel"><h3>Example {i} · {title}</h3><p>{q}</p>{a}</section>'
 out+='<h2 class="section-label">Problems 1–3 · Concept and mechanics</h2>'
 for i,(q,a,tag) in enumerate(d['problems'],1):
  if i==4:out+='<h2 class="section-label">Problems 4–5 · Application and explanation</h2>'
  if i==6:out+='<h2 class="section-label">Problem 6 · Transfer or counterexample</h2>'
  out+=f'<article class="problem" id="p{i}" data-problem="{prefix}-P{i}" data-skill="{tag}"><h3>{prefix}-P{i}</h3><p>{q}</p><label>Your attempt<textarea data-answer="{prefix}-P{i}" rows="3"></textarea></label><label>Support used<select data-support="{prefix}-P{i}"><option>Not recorded</option><option>Independent</option><option>Hint used</option><option>Solution consulted</option><option>Not attempted</option><option>Not reached</option></select></label>'+sol('<p>'+a+'</p>')+'</article>'
 out+=f'<article class="problem" data-problem="{prefix}-EXIT"><h2>Exit check · close examples and solutions</h2><p>{d["exit"][0]}</p><textarea aria-label="Exit response" data-answer="{prefix}-EXIT" rows="3"></textarea>'+sol('<p>'+d['exit'][1]+'</p>')+'</article>'
